// Portfolio gift sidebar. It renders the campaigns in gift-campaigns.js (generated by
// tools/aihankapps-gifts) and nothing else: no network requests, no storage, no admin surface.
// A campaign appears from its announcement time until its claim deadline; once nothing is
// current the sidebar is removed and the catalogue takes the full width again.
(() => {
  'use strict';

  // Interface strings only. Every sentence about a campaign comes from the data file.
  const UI = {
    'zh-TW': { entry: '禮包公告', details: '查看禮包詳情', upcoming: '即將開始', active: '進行中',
      toStart: '距離開始 {d} 天 {h} 時 {m} 分 {s} 秒', toEnd: '領取倒數 {d} 天 {h} 時 {m} 分 {s} 秒', history: '過去的活動' },
    'zh-CN': { entry: '礼包公告', details: '查看礼包详情', upcoming: '即将开始', active: '进行中',
      toStart: '距离开始 {d} 天 {h} 时 {m} 分 {s} 秒', toEnd: '领取倒计时 {d} 天 {h} 时 {m} 分 {s} 秒', history: '过去的活动' },
    en: { entry: 'Gift announcements', details: 'View gift details', upcoming: 'Coming soon', active: 'Live now',
      toStart: 'Starts in {d}d {h}h {m}m {s}s', toEnd: 'Time left to claim: {d}d {h}h {m}m {s}s', history: 'Past gifts' },
    ja: { entry: 'ギフトのお知らせ', details: 'ギフトの詳細を見る', upcoming: 'まもなく開始', active: '開催中',
      toStart: '開始まで {d}日 {h}時間 {m}分 {s}秒', toEnd: '受取期限まで {d}日 {h}時間 {m}分 {s}秒', history: '過去のギフト' },
    ko: { entry: '선물 공지', details: '선물 자세히 보기', upcoming: '곧 시작', active: '진행 중',
      toStart: '시작까지 {d}일 {h}시간 {m}분 {s}초', toEnd: '수령 마감까지 {d}일 {h}시간 {m}분 {s}초', history: '지난 선물' }
  };

  function localeOf(lang) {
    const value = String(lang || 'zh-Hant');
    if (/^zh-(Hant|TW|HK|MO)/i.test(value)) return 'zh-TW';
    if (/^zh/i.test(value)) return 'zh-CN';
    const base = value.split('-')[0].toLowerCase();
    return UI[base] ? base : 'en';
  }

  // hidden: not announced yet, or a record without public copy.
  function stateOf(campaign, now) {
    if (!campaign || !campaign.copy || !campaign.startsAt) return 'hidden';
    if (now < Date.parse(campaign.announceAt)) return 'hidden';
    if (now < Date.parse(campaign.startsAt)) return 'upcoming';
    if (now < Date.parse(campaign.claimEndsAt)) return 'active';
    return 'ended';
  }

  function countdown(template, remainingMs) {
    const remaining = Math.max(0, remainingMs);
    const parts = { d: Math.floor(remaining / 86400000), h: Math.floor(remaining / 3600000) % 24,
      m: Math.floor(remaining / 60000) % 60, s: Math.floor(remaining / 1000) % 60 };
    return template.replace(/\{([dhms])\}/g, (_, key) => (key === 'd' ? String(parts.d) : String(parts[key]).padStart(2, '0')));
  }

  // Everything the sidebar shows at one moment in one language. Live campaigns come first.
  function model(campaigns, now, lang) {
    const locale = localeOf(lang);
    const ui = UI[locale];
    const current = [];
    const past = [];
    for (const campaign of campaigns) {
      const state = stateOf(campaign, now);
      if (state === 'hidden') continue;
      const copy = campaign.copy[locale] || campaign.copy.en;
      if (state === 'ended') {
        past.push({ id: campaign.id, title: copy.title, summary: copy.ended });
        continue;
      }
      const target = Date.parse(state === 'upcoming' ? campaign.startsAt : campaign.claimEndsAt);
      current.push({ id: campaign.id, state, title: copy.title, badge: ui[state], lines: copy[state],
        countdown: countdown(state === 'upcoming' ? ui.toStart : ui.toEnd, target - now) });
    }
    current.sort((a, b) => (a.state === b.state ? 0 : a.state === 'active' ? -1 : 1));
    return { locale, ui, current, past, visible: current.length > 0 };
  }

  function element(doc, tag, props, children) {
    const node = doc.createElement(tag);
    for (const [key, value] of Object.entries(props || {})) {
      if (key === 'text') node.textContent = value;
      else if (key === 'className' || key === 'id' || key === 'open') node[key] = value;
      else node.setAttribute(key, value);
    }
    for (const child of children || []) node.appendChild(child);
    return node;
  }

  // Builds the whole sidebar for a view. `timers` collects the countdown nodes by campaign id.
  function build(doc, view, open, timers) {
    const ui = view.ui;
    const summary = element(doc, 'summary', { id: 'portfolioGiftEntry' }, [
      element(doc, 'span', { 'aria-hidden': 'true', text: '🎁 ' }),
      element(doc, 'span', { text: ui.entry }),
      element(doc, 'span', { className: 'gift-disclosure-hint', text: ui.details })
    ]);
    const children = [summary];
    if (view.current.length > 1) {
      children.push(element(doc, 'nav', { id: 'giftCampaignList', className: 'gift-campaign-list', 'aria-labelledby': 'portfolioGiftEntry' },
        view.current.map(card => element(doc, 'a', { href: '#' + card.id, text: card.title }))));
    }
    for (const card of view.current) {
      const timer = element(doc, 'p', { className: 'gift-countdown', role: 'timer', text: card.countdown });
      timers[card.id] = timer;
      children.push(element(doc, 'section', { id: card.id, className: 'rebound-gift', 'data-campaign-id': card.id,
        'data-state': card.state, 'aria-labelledby': card.id + '-title' }, [
        element(doc, 'h2', { id: card.id + '-title', text: card.title }),
        element(doc, 'p', { className: 'gift-badge', text: card.badge }),
        ...card.lines.map(line => element(doc, 'p', { text: line })),
        timer
      ]));
    }
    if (view.past.length) {
      children.push(element(doc, 'details', { className: 'gift-history' }, [
        element(doc, 'summary', { text: ui.history }),
        element(doc, 'ul', {}, view.past.map(item => element(doc, 'li', {}, [
          element(doc, 'strong', { text: item.title }),
          element(doc, 'span', { text: item.summary })
        ])))
      ]));
    }
    return element(doc, 'aside', { className: 'portfolio-gift-sidebar', 'aria-labelledby': 'portfolioGiftEntry' }, [
      element(doc, 'details', { id: 'game-gifts', className: 'portfolio-gift-disclosure', open }, children)
    ]);
  }

  function start(win, doc) {
    const campaigns = Array.isArray(win.AIHANK_GIFT_CAMPAIGNS) ? win.AIHANK_GIFT_CAMPAIGNS : [];
    const layout = doc.querySelector('.portfolio-layout');
    // Nothing can become current during this visit: stay inert.
    if (!layout || !campaigns.some(campaign => stateOf(campaign, Date.now()) !== 'ended' && campaign.copy && campaign.startsAt)) return;

    const desktop = win.matchMedia('(min-width: 980px)');
    const anchors = ['#game-gifts', ...campaigns.map(campaign => '#' + campaign.id)];
    const hashed = () => anchors.includes(win.location.hash);
    let aside = null;
    let timers = {};
    let signature = '';
    let open = desktop.matches || hashed();

    const refresh = force => {
      const view = model(campaigns, Date.now(), doc.documentElement.lang);
      const next = view.locale + '|' + view.current.map(card => card.id + ':' + card.state).join(',') + '|' + view.past.length;
      if (!force && next === signature) {
        for (const card of view.current) if (timers[card.id]) timers[card.id].textContent = card.countdown;
        return;
      }
      signature = next;
      if (aside) open = aside.firstChild.open;
      timers = {};
      const previous = aside;
      aside = view.visible ? build(doc, view, open, timers) : null;
      if (previous && aside) layout.replaceChild(aside, previous);
      else if (previous) layout.removeChild(previous);
      else if (aside) layout.insertBefore(aside, layout.firstChild);
    };
    const setOpen = value => {
      open = value;
      if (aside) aside.firstChild.open = value;
    };

    refresh(true);
    // The sidebar did not exist when the browser first looked for the anchor.
    if (aside && hashed() && win.location.hash !== '#game-gifts') {
      const target = doc.getElementById(win.location.hash.slice(1));
      if (target && target.scrollIntoView) target.scrollIntoView();
    }
    win.setInterval(refresh, 1000);
    new win.MutationObserver(() => refresh(true)).observe(doc.documentElement, { attributes: true, attributeFilter: ['lang'] });
    desktop.addEventListener('change', () => setOpen(desktop.matches || hashed()));
    win.addEventListener('hashchange', () => { if (hashed()) setOpen(true); });
  }

  if (typeof module !== 'undefined' && module.exports) module.exports = { UI, localeOf, stateOf, countdown, model, build, start };
  if (typeof window !== 'undefined' && typeof document !== 'undefined') start(window, document);
})();
